contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Force first transfer to fail: use a dummy token contract that always reverts
        // We'll deploy a simple token that reverts on transferFrom
        // But we can also make the first call revert by setting from = address(0) or other trick
        // Better: craft caddress to be a contract that reverts on first call but succeeds later
        // Since we cannot deploy inside fuzz, we use a simpler approach:
        // Ensure the first element of _tos is address(0) which will make the call revert
        // But the function calls transferFrom(from, _tos[i], v) so if _tos[0] = address(0), the call might succeed
        // Instead, we use the fact that if caddress is address(0), the call reverts
        // So we set caddress = address(0) to make the first call revert
        // Then the reference should revert, but mutant may skip first and succeed
        vm.assume(caddress == address(0));
        vm.assume(_tos.length >= 1);
        // For the reference, the first call should revert, causing the whole function to revert
        vm.expectRevert();
        c.transfer(from, caddress, _tos, v);
        // If we get here, the call did not revert (mutant behavior) – but we expect revert
        assertTrue(false, "reference should revert when first call fails");
    }
}

